/**
 * snar_ai.c — 千漉Mini 端侧AI推理引擎实现
 *
 * Auto-generated by SNARjs Phase F
 * ESP32 + PSRAM + SD Card (FAT32) 逐层推理
 * 支持 INT4 / INT8 / FP32 量化模型
 */

#include "snar_ai.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* ESP-IDF 头文件 (编译时由 ESP-IDF 提供) */
#ifdef ESP_PLATFORM
#include "esp_heap_caps.h"
#include "esp_log.h"
#include "esp_vfs_fat.h"
#include "driver/sdmmc_host.h"
#define SNAR_MALLOC(size) heap_caps_malloc(size, MALLOC_CAP_SPIRAM)
#define SNAR_FREE(ptr)    free(ptr)
#define SNAR_LOG(fmt, ...) ESP_LOGI("snar_ai", fmt, ##__VA_ARGS__)
#define SNAR_LOGE(fmt, ...) ESP_LOGE("snar_ai", fmt, ##__VA_ARGS__)
#else
/* 非ESP平台: 编译测试用桩 */
#define SNAR_MALLOC(size) malloc(size)
#define SNAR_FREE(ptr)    free(ptr)
#define SNAR_LOG(fmt, ...) printf("[snar_ai] " fmt "\n", ##__VA_ARGS__)
#define SNAR_LOGE(fmt, ...) fprintf(stderr, "[snar_ai] " fmt "\n", ##__VA_ARGS__)
#endif

/* ========== 内部函数 ========== */

/** INT4 反量化: 2个INT4 packed在一个byte里 */
static void dequant_int4(const uint8_t* packed, float* out, int n, float scale) {
    int idx = 0;
    for (int i = 0; i < (n + 1) / 2 && idx < n; i++) {
        int8_t lo = (int8_t)(packed[i] & 0x0F);
        if (lo > 7) lo -= 16;  /* sign extend */
        out[idx++] = (float)lo * scale;
        if (idx < n) {
            int8_t hi = (int8_t)((packed[i] >> 4) & 0x0F);
            if (hi > 7) hi -= 16;
            out[idx++] = (float)hi * scale;
        }
    }
}

/** INT8 反量化 */
static void dequant_int8(const uint8_t* packed, float* out, int n, float scale) {
    for (int i = 0; i < n; i++) {
        out[i] = (float)((int8_t)packed[i]) * scale;
    }
}

/** 矩阵向量乘: out[rows] = W[rows x cols] * x[cols] */
static void matvec(const float* W, const float* x, float* out, int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        float sum = 0.0f;
        const float* row = W + i * cols;
        for (int j = 0; j < cols; j++) {
            sum += row[j] * x[j];
        }
        out[i] = sum;
    }
}

/** RMSNorm: x[i] = x[i] / rms * weight[i] */
static void rms_norm(float* x, const float* weight, int dim) {
    float sum_sq = 0.0f;
    for (int i = 0; i < dim; i++) {
        sum_sq += x[i] * x[i];
    }
    float rms = sqrtf(sum_sq / dim + 1e-5f);
    float inv_rms = 1.0f / rms;
    for (int i = 0; i < dim; i++) {
        x[i] = x[i] * inv_rms * weight[i];
    }
}

/** Softmax in-place */
static void softmax(float* x, int n) {
    float max_val = x[0];
    for (int i = 1; i < n; i++) {
        if (x[i] > max_val) max_val = x[i];
    }
    float sum = 0.0f;
    for (int i = 0; i < n; i++) {
        x[i] = expf(x[i] - max_val);
        sum += x[i];
    }
    if (sum > 0.0f) {
        float inv_sum = 1.0f / sum;
        for (int i = 0; i < n; i++) {
            x[i] *= inv_sum;
        }
    }
}

/** SiLU activation: x[i] = x[i] * sigmoid(x[i]) */
static void silu(float* x, int n) {
    for (int i = 0; i < n; i++) {
        float s = 1.0f / (1.0f + expf(-x[i]));
        x[i] = x[i] * s;
    }
}

/** 从文件读取层权重到临时缓冲 */
static int load_layer_weights(snar_brain_t* brain, int layer_idx, float* out_buf) {
    snar_layer_record_t* layer = &brain->layers[layer_idx];
    int n_params = (int)(layer->rows * layer->cols);
    int raw_bytes = (int)layer->data_size;

    /* 分配原始字节缓冲 */
    uint8_t* raw = (uint8_t*)SNAR_MALLOC(raw_bytes);
    if (!raw) {
        SNAR_LOGE("无法分配 %d bytes 用于加载层权重", raw_bytes);
        return -1;
    }

    /* 读取文件 */
    FILE* fp = fopen(brain->model_path, "rb");
    if (!fp) {
        SNAR_FREE(raw);
        return -1;
    }
    fseek(fp, layer->data_offset, SEEK_SET);
    int nread = (int)fread(raw, 1, raw_bytes, fp);
    fclose(fp);

    if (nread != raw_bytes) {
        SNAR_LOGE("层 %d: 读取 %d/%d bytes", layer_idx, nread, raw_bytes);
        SNAR_FREE(raw);
        return -1;
    }

    /* 反量化 */
    switch (layer->quant) {
        case 4:
            dequant_int4(raw, out_buf, n_params, layer->scale);
            break;
        case 8:
            dequant_int8(raw, out_buf, n_params, layer->scale);
            break;
        case 32:
            memcpy(out_buf, raw, n_params * sizeof(float));
            break;
        default:
            SNAR_LOGE("不支持的量化: %d", layer->quant);
            SNAR_FREE(raw);
            return -1;
    }

    SNAR_FREE(raw);
    return 0;
}

/* ========== 公开 API ========== */

int snar_ai_load_model(snar_brain_t* brain, const char* model_path) {
    if (!brain || !model_path) return -1;

    memset(brain, 0, sizeof(snar_brain_t));
    strncpy(brain->model_path, model_path, sizeof(brain->model_path) - 1);

    /* 打开文件 */
    FILE* fp = fopen(model_path, "rb");
    if (!fp) {
        SNAR_LOGE("无法打开模型: %s", model_path);
        return -1;
    }

    /* 读取文件头 */
    snar_model_header_t* hdr = &brain->header;
    if (fread(hdr, 1, SNAR_AI_HEADER_SIZE, fp) != SNAR_AI_HEADER_SIZE) {
        SNAR_LOGE("读取文件头失败");
        fclose(fp);
        return -1;
    }

    /* 校验 magic */
    if (memcmp(hdr->magic, SNAR_AI_MAGIC, 8) != 0) {
        SNAR_LOGE("无效模型文件 (magic不匹配)");
        fclose(fp);
        return -1;
    }

    SNAR_LOG("模型加载: v%d, %d层, %d参数, dim=%d, heads=%d",
             hdr->version, hdr->n_layers, hdr->n_params,
             hdr->hidden_dim, hdr->n_heads);

    /* 读取层记录 (仅元数据，不读权重) */
    int n_layers = (int)hdr->n_layers;
    if (n_layers > SNAR_AI_MAX_LAYERS) {
        SNAR_LOGE("层数 %d 超过最大 %d", n_layers, SNAR_AI_MAX_LAYERS);
        fclose(fp);
        return -1;
    }

    for (int i = 0; i < n_layers; i++) {
        snar_layer_record_t* lr = &brain->layers[i];

        /* 读 layer header: type(1) + rows(4) + cols(4) + quant(1) + scale(4) + data_size(4) = 18 bytes */
        uint8_t type_byte;
        if (fread(&type_byte, 1, 1, fp) != 1) break;
        lr->layer_type = type_byte;

        if (fread(&lr->rows, 4, 1, fp) != 1) break;
        if (fread(&lr->cols, 4, 1, fp) != 1) break;
        if (fread(&lr->quant, 1, 1, fp) != 1) break;
        if (fread(&lr->scale, 4, 1, fp) != 1) break;
        if (fread(&lr->data_size, 4, 1, fp) != 1) break;

        lr->data_offset = ftell(fp);
        /* 跳过权重数据 */
        fseek(fp, lr->data_size, SEEK_CUR);

        brain->n_loaded_layers = i + 1;
    }

    fclose(fp);

    /* 分配 PSRAM 工作缓冲区 */
    int dim = (int)hdr->hidden_dim;
    int buf_floats = dim * 4; /* 至少4个 dim 大小的缓冲 */
    if (buf_floats < 1024) buf_floats = 1024;

    brain->work_buf = (float*)SNAR_MALLOC(buf_floats * sizeof(float));
    if (!brain->work_buf) {
        SNAR_LOGE("无法分配工作缓冲区 (%d floats)", buf_floats);
        return -1;
    }
    brain->attn_buf = (float*)SNAR_MALLOC(buf_floats * sizeof(float));
    if (!brain->attn_buf) {
        SNAR_LOGE("无法分配attention缓冲区");
        SNAR_FREE(brain->work_buf);
        brain->work_buf = NULL;
        return -1;
    }
    brain->buf_size = buf_floats;
    brain->initialized = 1;

    SNAR_LOG("模型加载完成: %d/%d 层, 工作缓冲 %d floats",
             brain->n_loaded_layers, n_layers, buf_floats);
    return 0;
}

int snar_ai_classify(snar_brain_t* brain, const float* input, int input_len,
                     const char** labels, int n_labels) {
    if (!brain || !brain->initialized || !input || input_len <= 0) return -1;
    if (n_labels <= 0 || n_labels > SNAR_AI_MAX_LABELS) return -1;

    int dim = (int)brain->header.hidden_dim;
    float* x = brain->work_buf;
    float* y = brain->attn_buf;

    /* 将输入复制到工作缓冲 */
    int copy_len = (input_len < dim) ? input_len : dim;
    memcpy(x, input, copy_len * sizeof(float));
    if (copy_len < dim) {
        memset(x + copy_len, 0, (dim - copy_len) * sizeof(float));
    }

    /* 逐层推理 */
    float* W = (float*)SNAR_MALLOC(dim * dim * 4 * sizeof(float)); /* 最大层临时缓冲 */
    if (!W) {
        SNAR_LOGE("无法分配权重缓冲");
        return -1;
    }

    for (int li = 0; li < brain->n_loaded_layers; li++) {
        snar_layer_record_t* lr = &brain->layers[li];
        int rows = (int)lr->rows;
        int cols = (int)lr->cols;

        switch (lr->layer_type) {
            case SNAR_LAYER_ATTN_QKV: {
                /* 简化: 仅取 Q 部分做线性变换 */
                int q_cols = cols; /* 实际 cols = hidden_dim * 3 for Q+K+V */
                if (rows * cols > brain->buf_size * (int)sizeof(float) / (int)sizeof(float)) {
                    /* 权重太大，分块加载 */
                    SNAR_LOG("层 %d: QKV 大矩阵 (%dx%d)", li, rows, cols);
                }
                if (load_layer_weights(brain, li, W) != 0) goto fail;
                /* 简化: 只计算 Q = W_q * x */
                matvec(W, x, y, rows, q_cols < dim ? q_cols : dim);
                memcpy(x, y, rows * sizeof(float));
                break;
            }
            case SNAR_LAYER_ATTN_OUT: {
                if (load_layer_weights(brain, li, W) != 0) goto fail;
                matvec(W, x, y, rows, cols);
                memcpy(x, y, rows * sizeof(float));
                break;
            }
            case SNAR_LAYER_FFN_UP: {
                if (load_layer_weights(brain, li, W) != 0) goto fail;
                matvec(W, x, y, rows, cols);
                silu(y, rows);
                memcpy(x, y, rows * sizeof(float));
                break;
            }
            case SNAR_LAYER_FFN_DOWN: {
                if (load_layer_weights(brain, li, W) != 0) goto fail;
                matvec(W, x, y, rows, cols);
                memcpy(x, y, rows * sizeof(float));
                break;
            }
            case SNAR_LAYER_RMS_NORM: {
                /* RMS norm 权重很小，直接加载 */
                float* norm_w = (float*)SNAR_MALLOC(cols * sizeof(float));
                if (!norm_w) goto fail;
                if (load_layer_weights(brain, li, norm_w) != 0) {
                    SNAR_FREE(norm_w);
                    goto fail;
                }
                rms_norm(x, norm_w, dim);
                SNAR_FREE(norm_w);
                break;
            }
            case SNAR_LAYER_OUTPUT: {
                /* 输出投影: hidden_dim -> vocab_size 或 n_labels */
                if (load_layer_weights(brain, li, W) != 0) goto fail;
                matvec(W, x, y, rows, cols);
                /* softmax 取前 n_labels */
                int out_dim = rows < n_labels ? rows : n_labels;
                softmax(y, out_dim);
                break;
            }
            default:
                SNAR_LOG("未知层类型: %d", lr->layer_type);
                break;
        }
    }

    SNAR_FREE(W);

    /* 找最大概率标签 */
    int best = 0;
    float best_score = y[0];
    for (int i = 1; i < n_labels; i++) {
        if (y[i] > best_score) {
            best_score = y[i];
            best = i;
        }
    }

    SNAR_LOG("分类结果: %s (%.3f)", labels[best], best_score);
    return best;

fail:
    SNAR_FREE(W);
    return -1;
}

void snar_ai_free(snar_brain_t* brain) {
    if (!brain) return;
    if (brain->work_buf) {
        SNAR_FREE(brain->work_buf);
        brain->work_buf = NULL;
    }
    if (brain->attn_buf) {
        SNAR_FREE(brain->attn_buf);
        brain->attn_buf = NULL;
    }
    brain->initialized = 0;
    SNAR_LOG("推理引擎已释放");
}
